#include <libssh2.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void fail(LIBSSH2_SESSION *s,const char* stage){char *m=NULL;int n=0;int code=s?libssh2_session_last_error(s,&m,&n,0):-1;fprintf(stderr,"LIB_ERROR %s %d\n",stage,code);exit(1);}
int main(int argc,char **argv){
 if(argc!=6)return 2;
 if(libssh2_init(0))return 3;
 int fd=socket(AF_INET,SOCK_STREAM,0);struct sockaddr_in addr={0};addr.sin_family=AF_INET;addr.sin_port=htons(atoi(argv[1]));inet_pton(AF_INET,"127.0.0.1",&addr.sin_addr);
 if(connect(fd,(struct sockaddr*)&addr,sizeof(addr)))return 4;
 LIBSSH2_SESSION *s=libssh2_session_init();if(!s)fail(s,"init");libssh2_session_set_blocking(s,1);libssh2_session_set_timeout(s,5000);
 if(libssh2_session_method_pref(s,LIBSSH2_METHOD_CRYPT_CS,"aes128-ctr")||libssh2_session_method_pref(s,LIBSSH2_METHOD_CRYPT_SC,"aes128-ctr")||libssh2_session_method_pref(s,LIBSSH2_METHOD_MAC_CS,"hmac-sha2-256")||libssh2_session_method_pref(s,LIBSSH2_METHOD_MAC_SC,"hmac-sha2-256"))fail(s,"algorithms");
 if(libssh2_session_handshake(s,fd))fail(s,"handshake");
 size_t keylen=0;int keytype=0;const char *key=libssh2_session_hostkey(s,&keylen,&keytype);if(!key||keytype!=LIBSSH2_HOSTKEY_TYPE_ED25519)fail(s,"hostkey-type");
 LIBSSH2_KNOWNHOSTS *known=libssh2_knownhost_init(s);if(!known)fail(s,"known-init");if(libssh2_knownhost_readfile(known,argv[4],LIBSSH2_KNOWNHOST_FILE_OPENSSH)<0)fail(s,"known-read");struct libssh2_knownhost *matched;
 if(libssh2_knownhost_checkp(known,"127.0.0.1",atoi(argv[1]),key,keylen,LIBSSH2_KNOWNHOST_TYPE_PLAIN|LIBSSH2_KNOWNHOST_KEYENC_RAW|LIBSSH2_KNOWNHOST_KEY_ED25519,&matched)!=LIBSSH2_KNOWNHOST_CHECK_MATCH)fail(s,"hostkey-check");
 libssh2_knownhost_free(known);
 if(libssh2_userauth_publickey_fromfile(s,argv[2],NULL,argv[3],""))fail(s,"auth");
 LIBSSH2_CHANNEL *c=libssh2_channel_open_session(s);if(!c)fail(s,"channel");
 if(libssh2_channel_request_pty(c,"xterm-256color"))fail(s,"pty");
 if(libssh2_channel_exec(c,argv[5]))fail(s,"exec");
 unsigned char bytes[65536];ssize_t n;while((n=libssh2_channel_read(c,(char*)bytes,sizeof(bytes)))>0){if(fwrite(bytes,1,n,stdout)!=(size_t)n)return 7;fflush(stdout);}
 if(n<0)fail(s,"read");libssh2_channel_wait_eof(c);libssh2_channel_close(c);libssh2_channel_wait_closed(c);int code=libssh2_channel_get_exit_status(c);libssh2_channel_free(c);libssh2_session_disconnect(s,"test finished");libssh2_session_free(s);close(fd);libssh2_exit();return code;
}
